def icon(name: str, size: int = 16, label: str = "") -> Markup:
    """An inline SVG in the text colour. Decorative (hidden from screen
    readers) unless `label` names it, for a button with no text."""
    a11y = f' role="img" aria-label="{Markup.escape(label)}"' if label else ' aria-hidden="true"'
    return Markup(f'<svg class="icon" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
                  f'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
                  f'focusable="false"{a11y}>{SHAPES[name]}</svg>')
